CREATE TABLE vendor_work_sections (vendor_id BIGINT UNSIGNED NOT NULL,work_section_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(vendor_id,work_section_id),KEY idx_vendor_work_sections_section(work_section_id),CONSTRAINT fk_vendor_work_sections_vendor FOREIGN KEY(vendor_id) REFERENCES vendors(id) ON DELETE CASCADE,CONSTRAINT fk_vendor_work_sections_section FOREIGN KEY(work_section_id) REFERENCES work_sections(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
